begin;
create table if not exists public.organization_roles(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,name text not null,description text,is_system boolean not null default false,is_active boolean not null default true,created_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,name));
create table if not exists public.organization_member_roles(membership_id uuid not null references public.organization_members(id) on delete cascade,role_id uuid not null references public.organization_roles(id) on delete cascade,assigned_by uuid references auth.users(id) on delete set null,assigned_at timestamptz not null default now(),primary key(membership_id,role_id));
alter table public.organization_roles enable row level security; alter table public.organization_member_roles enable row level security;
create policy "members read custom roles" on public.organization_roles for select using(exists(select 1 from public.organization_members m where m.organization_id=organization_roles.organization_id and m.user_id=auth.uid()));
create policy "admins manage custom roles" on public.organization_roles for all using(exists(select 1 from public.organization_members m where m.organization_id=organization_roles.organization_id and m.user_id=auth.uid() and m.role in('owner','admin'))) with check(exists(select 1 from public.organization_members m where m.organization_id=organization_roles.organization_id and m.user_id=auth.uid() and m.role in('owner','admin')));
commit;
